// ============================================================================
// Ethernet_apb: APB4 register wrapper around Ethernet_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Ethernet.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Ethernet.md
// ============================================================================
module Ethernet_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [7:0] gtxd,
  output logic gtx_en,
  output logic gtx_er,
  input logic [7:0] grxd,
  input logic grx_dv,
  input logic grx_er
);
  localparam logic [31:0] ID_VALUE = 32'h45540200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [10:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd11) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [4:0]    c_cfg_div;
  logic [47:0]   c_cfg_mac;
  logic          c_cfg_promisc;
  logic          c_cfg_pause_en;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [7:0]    c_tx_data;
  logic          c_tx_last;
  logic          c_tx_done;
  logic          c_tx_underrun;
  logic          c_tx_paused;
  logic          c_rx_valid;
  logic [7:0]    c_rx_data;
  logic          c_rx_last;
  logic [3:0]    c_rx_stat;
  logic          c_rx_frag;
  Ethernet_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_div(c_cfg_div),
    .cfg_mac(c_cfg_mac),
    .cfg_promisc(c_cfg_promisc),
    .cfg_pause_en(c_cfg_pause_en),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_last(c_tx_last),
    .tx_done(c_tx_done),
    .tx_underrun(c_tx_underrun),
    .tx_paused(c_tx_paused),
    .gtxd(gtxd),
    .gtx_en(gtx_en),
    .gtx_er(gtx_er),
    .grxd(grxd),
    .grx_dv(grx_dv),
    .grx_er(grx_er),
    .rx_valid(c_rx_valid),
    .rx_data(c_rx_data),
    .rx_last(c_rx_last),
    .rx_stat(c_rx_stat),
    .rx_frag(c_rx_frag)
  );

  // ---------------- registers ----------------
  logic [6:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [6:0] r_CFG;   // 12'h014 CFG
  logic [31:0] r_MAC0;   // 12'h018 MAC0
  logic [15:0] r_MAC1;   // 12'h01C MAC1
  logic [8:0] h_TX;   // 12'h020 TX holding register
  logic [12:0] h_RX;   // 12'h024 RX holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 7'h5F;
      r_MAC0 <= 32'h0;
      r_MAC1 <= 16'h0;
      h_TX <= '0;
      h_RX <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[6:0] & wmask[6:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[6]) r_MAC0 <= (r_MAC0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_MAC1 <= (r_MAC1 & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[8] && !full_TX) h_TX <= (h_TX & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[8] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[9]))) begin
        h_RX[7:0] <= c_rx_data[7:0];
        h_RX[8:8] <= c_rx_last;
        h_RX[12:9] <= c_rx_stat[3:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[9]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_div = r_CFG[4:0];
  assign c_cfg_promisc = r_CFG[5:5];
  assign c_cfg_pause_en = r_CFG[6:6];
  assign c_cfg_mac[31:0] = r_MAC0[31:0];
  assign c_cfg_mac[47:32] = r_MAC1[15:0];
  assign c_tx_data[7:0] = h_TX[7:0];
  assign c_tx_last = h_TX[8:8];
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_done;
    irq_set[1] = c_tx_underrun;
    irq_set[2] = c_rx_frag;
    irq_set[3] = full_TX & c_tx_ready;
    irq_set[4] = wr & (hit[8]) & full_TX;
    irq_set[5] = c_rx_valid & (~avail_RX | (rd & hit[9]));
    irq_set[6] = c_rx_valid & avail_RX & ~(rd & hit[9]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG);
      10'd6: apb_rdata = 32'(r_MAC0);
      10'd7: apb_rdata = 32'(r_MAC1);
      10'd8: apb_rdata = 32'(h_TX);
      10'd9: apb_rdata = 32'(h_RX);
      10'd10: apb_rdata = 32'({c_tx_paused});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
